import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { BuildingEntity } from '../Entity/BuildingEntity';
import { HallEvents } from '../HallEvents';

export interface MonthlyReport {
    month: number;
    totalBuildings: number;
    totalIncomePerSecond: number;
    totalPending: number;
    bonusCoins: number;
    stars: number;
}

export class SettlementSystem implements System {
    private _world: World = null!;
    private _month = 0;

    onStart(world: World): void {
        this._world = world;
        world.bus.on(HallEvents.MONTH_PASSED, this._onMonthPassed, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.MONTH_PASSED, this._onMonthPassed, this);
        this._world = null!;
    }

    onTick(): void {}

    private _onMonthPassed(): void {
        this._month++;
        const report = this._buildReport();
        this._world.bus.emit(HallEvents.MONTHLY_REPORT, report);

        if (report.bonusCoins > 0) {
            this._world.bus.emit(HallEvents.REWARD_GRANT_REQUEST, { coins: report.bonusCoins });
        }
    }

    private _buildReport(): MonthlyReport {
        let totalBuildings = 0;
        let totalIncomePerSecond = 0;
        let totalPending = 0;

        for (const b of this._world.query<BuildingEntity>('building')) {
            totalBuildings++;
            totalIncomePerSecond += b.effectiveIncomePerSecond;
            totalPending += b.pendingIncome;
        }

        // 月奖励 = 当月产出速率的 10%，按 60 秒折算
        const bonusCoins = Math.floor(totalIncomePerSecond * 60 * 0.1);
        // 星级：按建筑数量粗略分档
        const stars = totalBuildings >= 8 ? 3 : totalBuildings >= 4 ? 2 : 1;

        return { month: this._month, totalBuildings, totalIncomePerSecond, totalPending, bonusCoins, stars };
    }
}